INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (1, 0, '六气图', NULL, '  六气图就是十二个时辰循环走向，如果从一天分阴阳，看那个阴阳的太极图，是一个圆的，不是一条线，没有瞬间就天黑的，瞬间就是白天，没有这种事，慢慢慢慢天黑，慢慢慢慢白天，这就是说阴和阳是慢慢慢慢在转换的。\n  十二个时辰里面，分六个气，\n      第一个蕨阴气，亥时-已时，这两个时辰是相对的，蕨阴的意思就是阴的刚开始的时候，它是阳准备结束了，阴开始初进的时候\n      第二个少阴气，子时-午时,是少阴，\n      第三个太阴气，丑-未时，是太阴，\n      第四个少阳气，寅-申时,是少阳，阳开始起来了一点，\n      第五个阳明气，卯-酉时,是阳明，\n      第六个太阳气，辰-戌时,叫做太阳，\n  这个是一天的六气，它的循环六气', '六气图', 'Upload/Images/2024-11-14/hid4oOJCpnXmR0k6wFhPqEIRu3zzdcDj.png', '易理', 9040000, 599948047433797, '2A2BEEE90AA3D34128E5217FE4BB73C7', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2024-09-15 08:56:57', 1, '超级管理员', '2024-11-19 09:24:53');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (2, 1, '八纲辨症', NULL, '中医所谓的八纲辨症，阴,阳,表,里,虚,实,寒,热。', '中医八纲辨症', NULL, '医理', 9040000, 613701416611909, '4377261BA050785F1A43E23B8C928104', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 13:37:29', 1, '超级管理员', '2024-11-19 17:13:38');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (3, 2, '太阳', NULL, '对于太阳,可以代表经络中的太阳经,也可以代表全体阴阳状态的太阳。\n八纲辨症中表里的“表”,在这里指的就是太阳。\n病如果是外来的，初犯的时候一定是在表，病在外面，表就是在外面。张仲景把这个表就叫做太阳。\n太阳为寒水所以常人皮肤表面是冰凉的手脚是温热的,体表有这太阳的寒水,可以保卫我们不受外界寒热的影响,调节体温。这寒水不是停滞的,是不断的代谢更的。', NULL, NULL, '医理', 9040000, 613709833875525, '5DD057A4B26D509C906995FE952B0960', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 14:11:44', 1, '超级管理员', '2024-11-19 17:13:42');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (4, 3, '真寒假热', NULL, '面色：两颧色红，界限分明，红部虽鲜艳，而不红部则白中带青。  \n\n口鼻气：呼出气不温，且不急促，气亦不臭。 舌形：舌虽干而质淡，或红而质润。  \n\n脉象：脉虽浮数，按之则无力。  \n\n按胸腹：胸腹部按之不蒸手，初按似热，久按不如平人，不觉甚热。', NULL, NULL, '医理', 9040000, 613754343915589, '4573D2C1262E105FA837810F8CA8ED30', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:12:51', 1, 'admin', '2025-02-11 11:02:30');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (5, 4, '真热假寒', NULL, '面色：面色表虽冷，面色虽滞，两目则炯炯有神。 口鼻气：呼出气必温，且急促，或有不臭。 舌形：舌虽干而质燥，苔虽薄而根必厚，或黄而疏松，或润而齿枯。  \n\n脉象：脉虽沉细，必兼数急。  \n\n按胸腹：四肢虽寒，胸腹必热，久按且蒸蒸有热气感。  \n\n以后我们会常看到上寒下热，而不用真寒假热、或真热假寒，看到上热下寒，就是告诉你去热和去寒的药必须同用。  \n\n医圣张仲景在伤寒论中不谈阴虚内热，他用的是阴盛、阴亡、阳盛、阳亡，所谓的阴盛就是阴实，阳盛就是阳实。温病派的医生看到每个人都是阴虚，都想到用补药，但是张仲景治病的时候不用补药。他治病的时候小补的时候用炙甘草，中补用大枣、白芍，大补的时候加人参，补阴的药顶多就是这样，反而阳药用的很多。所以治病的时候不用补药。那什么时候吃补药？身体健康的时候才吃补药。这与温病派的观念完全不同。  ', NULL, NULL, '医理', 9040000, 613754761302085, '34E7371E1F160FB0D14DEAE149C88BC9', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-19 17:14:33', 1, 'admin', '2025-02-11 11:02:23');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (6, 5, '乳房硬块', NULL, '乳房硬块', '乳房硬块', 'Upload/Images/2024-11-22/8ALeAta6JLu4wRvbUA3lv7ytRMhpWa7h.jpg', '医理', 9040000, 614738963951685, '0BB5072F7254CB08FF7DF53B06DBBB4E', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-22 11:59:17', NULL, NULL, NULL);
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (7, 6, '判断瘀血的', NULL, '判断瘀血的方法  \n\n      一、血会膈俞，病人一定会有膈俞痛，督脉第七椎外开一寸半，就是膈俞穴。  \n\n      二、舌有齿痕 ，舌头上有牙齿的痕迹，因为舌为心表，心主血，身上循环系统很好的时候，舌头会很光润，循环不好的时候，舌头的循环也会跟着不好，舌头跟牙齿贴到，一拉开来，牙齿印还在上面，就代表瘀血，很多都是妇科子宫的问题。 \n\n       三、血海痛，足太阴脾经上的血海穴会痛。 \n\n       四、三阴交，三阴交有压痛点，三阴交痛大多在妇科里面，三阴交主腹、少腹的地方。\n\n       五、更严重的，在肚子上看到一块一块的青紫。  \n\n       六、口渴而不欲饮。  \n\n        张仲景在设计桃核承气汤的时候，考虑把瘀血攻下来，而不要把正常的体能伤到，把坏的攻下去，好的留下来，如何这药一吃，刚好把瘀血攻下来？所以桃核承气汤主要是靠桃仁和桂枝，桃仁专门破血，行血化瘀，所以桃仁用的很多，包括生化汤里面都有桃仁，桃核承气汤实际上就是利用调胃承气汤加减而成。张仲景破除瘀血的时候，会利用桂枝强心、辛香发散的特性，来加强心脏推动血液的力量，然后配合其它破瘀血的药，如此破除瘀血的力量就会增强。  \n\n       临床上，遇到久病的病人，想要开补血药的时候，记得要先去瘀血，所谓瘀不去，新不生，不是一味地开补药就好。  \n', NULL, NULL, '医理', 9040000, 615769397715013, 'A1874D97F4E2A6B9D77AD61CED0730CE', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-25 09:52:08', NULL, NULL, NULL);
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (8, 7, '肉上粟起', NULL, '皮肤上鸡皮疙瘩起得很多', '肉上粟起', NULL, '通用', 9040000, 616147400900677, '5EAE565DC5314DB9F1DF431ABE42513C', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-26 11:30:14', NULL, NULL, NULL);
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (9, 8, '瞤', NULL, '瞤即胸痛 \n$a{桂版。伤寒论-辨咳嗽水饮黄汗历节病脉证并治} \n       黄汗之病，两胫自冷，假令发热，此属历节，食已汗出，暮常盗汗，此荣气热也；若汗出已，反发热者，久久身必甲错；若发热不止者，久久必生恶疮；若身重，汗出已辙，轻者，久久身必$m{瞤}，$m{瞤即胸痛}；又从腰以上汗出，以下无汗，腰臗弛痛，如有物在皮中状，剧则不能食，身疼重，烦躁，小便不利，此为黄汗，桂枝加黄芪汤主之。', NULL, NULL, '医理', 1001000, 623586718924869, '00B0DC10FA0888E15D9D9D962F453E89', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-17 12:00:53', 1, 'admin', '2025-01-16 10:40:59');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (10, 9, '单行', NULL, '用一味药治疗疾病谓单行。如人参治疗气虚欲脱证；马齿苋治疗痢疾。', NULL, NULL, '药理', 400100, 634183577518149, '6DC1EE2A70DC53AED1559D8A9D8E0BF4', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 10:39:37', 1, 'admin', '2025-01-16 10:40:52');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (11, 10, '须', NULL, '    相须就是两种功效类似的药物配合应用，可以增强原有药物的功效。$m{相须、相使}表示$m{增效}，临床用药要充分利用；如麻黄配枝枝，能增强发汗解表、祛风散寒的作用，它构成了复方用药的配伍核心，是中药配伍应用的主要形式之一。', NULL, NULL, '药理', 400100, 634183844937797, '168F4F99F092FE4B5A98186C26615785', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 10:40:42', 1, 'admin', '2025-01-16 11:40:38');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (12, 11, '使', NULL, '相使就是以一种药物为主，另一种药物为辅，两药合用，辅药可以提高主药的功效。相须、相使表示增效，临床用药要充分利用；如黄芪配茯苓治脾虚水肿，黄芪为健脾益气、利尿消肿的主药，茯苓淡渗利湿，可增强黄芪益气利尿的作用。这是功效不同相使配伍的例证，可见相使配伍药不必同类。一主一辅，相辅相成，辅药能提高主药的疗效，即是相使的配伍。', NULL, NULL, '药理', 400100, 634184059588677, 'EED8AC0105E7918280600EDEE08A7BB6', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 10:41:35', 1, 'admin', '2025-01-16 11:39:35');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (13, 12, '畏\n', NULL, '相畏就是一种药物的毒副作用能被另一种药物所抑制。相畏、相杀表示减毒，应用毒烈药时须考虑选用；如半夏畏生姜，即生姜可以抑制半夏的毒副作用。 ', NULL, NULL, '药理', 400100, 634184227987525, 'D878D2184204BDE68344AE916748754C', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 10:42:16', 1, 'admin', '2025-01-16 11:39:29');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (14, 13, '杀', NULL, '相杀就是一种药物能够消除另一种药物的毒副作用。相畏、相杀表示减毒，应用毒烈药时须考虑选用；', NULL, NULL, '药理', 400100, 634184374788165, '8A4918F8DEDB6CF536AF3675EFEC73AF', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 10:42:52', 1, 'admin', '2025-02-11 11:02:14');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (15, 14, '恶', NULL, '相恶就是一种药物能破坏另一种药物的功效。相恶表示减效，用药时应加以注意；如人参恶莱菔子，莱菔子能削弱人参的补气作用。', NULL, NULL, '药理', 400100, 634184602390597, 'EB3D3401A635BEA4BB9315CF1CA828EA', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 10:43:47', 1, 'admin', '2025-01-16 11:39:11');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (16, 15, '反', NULL, '相反就是两种药物同用能产生剧烈的毒副作用。相反表示增毒，原则上应绝对禁止。如甘草反甘遂，贝母反乌头等，详见用药禁忌“十八反”、“十九畏”中若干药物。', NULL, NULL, '药理', 400100, 634185264443461, 'EA7CACCE78E1A94BC39D04359BFEF430', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 10:46:29', 1, 'admin', '2025-01-16 11:39:06');
INSERT INTO `MingCi` (`MingCiId`, `MingCiNo`, `MingCiName`, `MingCiBeiMing`, `MingCiText`, `MingCiList`, `ShowImage`, `MingCiType`, `SoureBook`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (17, 16, '肾虚', NULL, '        中医认为肾藏精，肾精化生出肾阴和肾阳，对五脏六腑起到滋养和温煦的作用。肾阴和肾阳在人体内相互依存、相互制约，维持人体的生理平衡。如果这一平衡遭到破坏或者某一方衰退就会发生病变，导致肾阳虚或肾阴虚。\n\n肾阴虚和肾阳虚区分\n     中医认为，肾阴虚和肾阳虚的区别在于：$n{肾阴}是物质上的缺乏，主怕$n{热}；$m{肾阳}是功能上的匮乏，主怕$m{冷}。\n\n肾阴虚的症状有：\n     虚热，具体表现为$m{腰酸背疼、头晕耳鸣、心烦气躁、失眠盗汗、舌质红、舌苔少而干}等。女性会出现$m{月经不调、月经推迟、月经量少、闭经}；男性会出现$m{早泄、不举、梦遗}。\n\n肾阳虚的症状有：\n      虚寒，具体表现为$m{手脚冰冷、疲惫乏力、精神不振、腰膝酸软冷痛}。女性常见$m{宫寒}，男性常见$m{阳痿}，影响生育。\n\n肾阴虚和肾阳虚区分\n        肾阴虚和肾阳虚有相似的症状，比如$x{四肢乏力、腰酸背痛、精神不振}等。如何区分呢？\n\n1、看寒热。\n       $n{肾阴虚}主要以虚热为临床表现，肾阴虚的人$n{晚上睡觉容易出汗，手心、脚心潮热，容易口干，小便发黄}。\n       $m{肾阳虚}主要以虚寒为临床表现，与肾阴虚相反，肾阳虚的人$m{会出现四肢冰冷、腹泻、小便清长}等症状。\n\n2、看出汗。 肾阴虚和肾阳虚都会有出汗的症状，\n        肾阴虚多表现为$n{盗汗}，\n        肾阳虚多表现为$m{虚汗}。\n\n3、看舌苔。\n        肾阴虚的人舌苔$n{发红，苔薄}；\n        肾阳虚的人舌苔$m{发白，苔厚}。\n\n4、看面色。\n        肾阴虚的人$n{面色潮红}；\n        肾阳虚的人$m{面色发白}。\n\n5、看精神。\n        肾阴虚的人$m{易燥易怒，烦躁不安}；\n        肾阳虚的人$m{精神萎靡，郁郁寡欢}。\n\n肾阴虚和肾阳虚的原因：肾阴又称$n{元阴、真阴、肾水，是全身阴液的根本}，是由于肾脏阴气或者阴液亏损无法滋养肾脏造成的。\n肾阴虚的原因，包括：\n                           操劳过度，阴精暗耗；\n                           纵欲过度，房事不节，肾精流失过多；\n                           经常熬夜，睡眠不足，耗伤阴精；\n                           常吃煎炸类食物，容易上火，伤阴；\n                           生病时间长，身体机能下降，肾脏阴液耗损；\n                           内伤七情，大悲大喜、情绪低落、脾气暴躁，容易伤肾。\n\n肾阳为人$m{体阳气之根，具有温煦脏器的功能，是人体一切功能活动的原动力}。阳虚不得温煦，阴寒内生，故见阳虚诸证，出现阳虚阴盛、虚寒内生的症状。\n肾阳虚的原因，包括：\n              先天性肾脏不足，温煦功能下降；\n              年老体弱，累及肾脏，导致阳气虚衰；\n             长期生病，免疫力下降，肾阳虚；\n             生活不规律，人体消耗过度；\n             房事过度，毫无节制，耗伤肾阳。\n\n治疗肾阴虚和肾阳虚， 除了养成健康的饮食和生活习惯之外，有一些中药也可以帮助治疗肾虚。\n\n肾阳虚：黄芪、肉桂、山药\n         黄芪，药性甘，微温，主入脾经，具有利尿消肿、补益肺气、益卫固表、补虚通滞等功效。\n         肉桂，辛、甘，大热，属辛温食物，可以温阳散寒、补火助阳，可用于肾虚作喘、心腹冷痛、虚寒吐泻等。\n         山药，味甘、性平，入肺、脾、肾经，主治肾气亏耗、脾胃虚弱、遗精早泄等病症。\n\n肾阴虚：何首乌、熟地黄、桑葚\n\n       何首乌，苦甘涩、微温，归肝、心、肾经，具有安神、养血、活络，解毒、消痈等功效。\n       熟地黄，味甘、性微温，入于心、肝、肾经，是补血生精、滋阴补肾退热的重要药材。\n       桑葚，甘、酸，寒，归心、肝、肾经，主治肝肾阴虚、心悸失眠、津伤口渴等病症。\n', '肾阳虚,肾阴虚', NULL, '医理', 20300000, 643390308855877, 'E49201D7A9DBB7AA8B64C76B48A07EFD', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-02-11 11:01:54', 1, 'admin', '2025-02-11 11:06:56');
